import { NextFunction, Request, Response } from "express";
import { DomainError, DomainErrorKind } from "../domain/DomainError";
import { BadRequestError } from "./OrderController";

const STATUS_BY_KIND: Record<DomainErrorKind, number> = {
  not_found: 404,
  conflict: 409,
  invalid: 400,
};

export function errorMiddleware(error: unknown, _req: Request, res: Response, _next: NextFunction): void {
  if (error instanceof DomainError) {
    res.status(STATUS_BY_KIND[error.kind]).json({ error: error.message });
  } else if (error instanceof BadRequestError) {
    res.status(400).json({ error: error.message });
  } else if (error instanceof SyntaxError) {
    res.status(400).json({ error: "Malformed JSON body" });
  } else {
    res.status(500).json({ error: "Internal server error" });
  }
}

